<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class OfficeRegistrationService{
public function register(int $documentId,int $userId,?int $correspondentId=null,?string $method=null):string{return DB::transaction(function()use($documentId,$userId,$correspondentId,$method){$d=DB::table('official_documents')->lockForUpdate()->find($documentId);abort_if(!$d,404);$old=DB::table('office_registrations')->where('official_document_id',$documentId)->first();if($old)return $old->registration_number;$reg=DB::table('office_registers')->where(['direction'=>$d->direction,'active'=>1])->lockForUpdate()->first();abort_if(!$reg,422,'Нет журнала для направления '.$d->direction);$year=(int)date('Y');$next=(int)$reg->next_number;if($reg->reset_yearly&&(int)$reg->current_year!==$year)$next=1;$number=sprintf('%s-%d-%05d',$reg->prefix,$year,$next);DB::table('office_registers')->where('id',$reg->id)->update(['next_number'=>$next+1,'current_year'=>$year,'updated_at'=>now()]);DB::table('office_registrations')->insert(['official_document_id'=>$documentId,'office_register_id'=>$reg->id,'registration_number'=>$number,'registration_date'=>date('Y-m-d'),'office_correspondent_id'=>$correspondentId,'delivery_method'=>$method,'received_at'=>$d->direction==='incoming'?now():null,'registered_by'=>$userId,'created_at'=>now(),'updated_at'=>now()]);DB::table('official_documents')->where('id',$documentId)->update(['status'=>'registered','registered_at'=>now(),'registered_by'=>$userId,'correspondent'=>$correspondentId?DB::table('office_correspondents')->where('id',$correspondentId)->value('name'):$d->correspondent,'updated_at'=>now()]);DB::table('official_document_events')->insert(['official_document_id'=>$documentId,'user_id'=>$userId,'event'=>'office_registered','details'=>'Рег. № '.$number,'created_at'=>now(),'updated_at'=>now()]);return $number;});}
}